  ('fp-g00946', 'forest-production', 'silvicultural-methods-systems', 'Hard', 'mock',
   'Which characteristic distinguishes the uniform shelterwood method from the group shelterwood method in silviculture?',
   '[{"id":"a","text":"Uniform shelterwood removes all mature trees at once, while group shelterwood does it in stages."},{"id":"b","text":"Uniform shelterwood focuses on regenerating shade-intolerant species, whereas group shelterwood targets shade-tolerant species."},{"id":"c","text":"Group shelterwood creates uniform seedling patches, while uniform shelterwood fosters regeneration throughout the stand."},{"id":"d","text":"Group shelterwood involves clearcutting small groups, while uniform shelterwood uses thinning across the stand."}]'::jsonb, 'c'),
